    }
}
public sealed class NativeFileDigest {public string Hash;public long Length;}
public sealed class NativeTree {
    public string Root;public Dictionary<string,NativeFileDigest> Files=new Dictionary<string,NativeFileDigest>(StringComparer.OrdinalIgnoreCase);public HashSet<string> Directories=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public static NativeTree Read(string root){NativeData.NoLinks(root);if(!Directory.Exists(root))throw new DirectoryNotFoundException("组件目录缺失："+root);var tree=new NativeTree{Root=Path.GetFullPath(root)};tree.Walk(tree.Root);return tree;}
    void Walk(string directory){foreach(var path in Directory.GetFileSystemEntries(directory)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("运行时包含链接，停止修改："+path);var relative=path.Substring(Root.TrimEnd('\\').Length+1);if(Directory.Exists(path)){Directories.Add(relative);Walk(path);}else{var info=new FileInfo(path);Files.Add(relative,new NativeFileDigest{Hash=NativeCua.Hash(path),Length=info.Length});}}}
    public bool Same(string target){if(!Directory.Exists(target))return false;var other=Read(target);if(Files.Count!=other.Files.Count||!Directories.SetEquals(other.Directories))return false;foreach(var item in Files){NativeFileDigest current;if(!other.Files.TryGetValue(item.Key,out current))return false;if(item.Value.Length!=current.Length||item.Value.Hash!=current.Hash)return false;}return true;}
    public void CopyTo(string target){Directory.CreateDirectory(target);foreach(var dir in Directories)Directory.CreateDirectory(Path.Combine(target,dir));foreach(var file in Files.Keys){var dest=Path.Combine(target,file);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(Path.Combine(Root,file),dest,false);}}
}
public sealed class NativeBrowserPatch {
    public string Relative,OriginalHash,PatchedHash;
    public sealed class Record {public int schema;public string runtimeId,source,target,originalHash,patchedHash,packageFullName,proxy;}
    public static NativeBrowserPatch Load(NativePaths p,OfficialDesktop app,string target){
