        if(record==null||record.schema!=1||record.runtimeId!=id||!String.Equals(record.source,app.Source,StringComparison.OrdinalIgnoreCase)||!String.Equals(record.target,target,StringComparison.OrdinalIgnoreCase)||record.packageFullName!=app.FullName)throw new InvalidDataException("浏览器补丁版本或来源不匹配，停止覆盖。");
