        var patched=LegacyContent(original,record.proxy);var patchedHash=NativeCua.HashBytes(patched);if(patchedHash!=record.patchedHash)throw new InvalidDataException("浏览器补丁校验不符。");var relative=launchers[0].Substring(app.Source.TrimEnd('\\').Length+1);var launcher=Path.Combine(target,relative);if(!File.Exists(launcher))throw new FileNotFoundException("受管理浏览器入口缺失，需先单独恢复浏览器连接。",launcher);var current=NativeCua.Hash(launcher);if(current!=originalHash&&current!=patchedHash)throw new InvalidDataException("浏览器入口包含未识别修改，停止覆盖。");return new NativeBrowserPatch{Relative=relative,OriginalHash=originalHash,PatchedHash=patchedHash};
    }
    static byte[] LegacyContent(byte[] original,string proxy){var text=NativeData.Utf8.GetString(original);if(NativeData.Normalize(text.TrimStart('\uFEFF')).TrimEnd('\n')!=NativeData.Resource("BrowserLauncher.mjs").TrimEnd('\n'))throw new InvalidDataException("未知浏览器入口结构，停止覆盖。");Uri uri;System.Net.IPAddress ip;if(!Uri.TryCreate(proxy,UriKind.Absolute,out uri)||uri.Scheme!="http"||uri.UserInfo.Length>0||uri.AbsolutePath!="/"||uri.Query.Length>0||uri.Fragment.Length>0||!System.Net.IPAddress.TryParse(uri.DnsSafeHost.Trim('[',']'),out ip)||uri.Port<1||uri.Port>65535)throw new InvalidDataException("受管理浏览器代理地址无效。");
        var values=new Dictionary<string,string>{{"HTTP_PROXY",proxy},{"HTTPS_PROXY",proxy},{"NO_PROXY","localhost,127.0.0.1,::1"},{"NODE_USE_ENV_PROXY","1"}};string newline=text.Contains("\r\n")?"\r\n":"\n";var inject=NativeData.Resource("LegacyBrowserInjection.txt").Replace("__VALUES__",NativeData.Json.Serialize(values)).Replace("\n",newline)+newline;return Encoding.UTF8.GetBytes(text.Replace("try {",inject+"try {"));}
}
public sealed class NativeCuaResult {public bool Changed,Passed;public string RuntimeId,Target,Backup,Report;}
public sealed class NativeCua {
    readonly NativePaths paths;readonly NativeServices services;public Action<NativeTree,string> Copy;
    public NativeCua(NativePaths p,NativeServices s){paths=p;services=s;Copy=(tree,target)=>tree.CopyTo(target);}
    public static string Hash(string path){using(var sha=SHA256.Create())using(var file=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant();}
    public static string HashBytes(byte[] data){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
