                string sourceHash=@"function\s+(?<collector>[$\w]+)\(\{destinationPath:(?<dest>[$\w]+),executableName:(?<exe>[$\w]+),sourcePath:(?<path>[$\w]+)\}\)\{[\s\S]{0,1800}?return\{digest:"+Regex.Escape(stream.Groups["hashFn"].Value)+@"\(\{destinationPath:\k<dest>,executableName:\k<exe>,filePath:\k<path>,operation:"+q+@"hash_source"+q+@",sourcePath:\k<path>\}\),executableName:\k<exe>,";
                var source=Regex.Match(code,sourceHash);if(source.Success){string list=@"(?<list>[$\w]+)="+markers+@"\.map\((?<item>[$\w]+)=>"+Regex.Escape(source.Groups["collector"].Value)+@"\(\{destinationPath:[$\w]+,executableName:\k<item>,sourcePath:\(0,[$\w]+\.join\)\([$\w]+,\k<item>\)\}\)\),[$\w]+="+Regex.Escape(found.Groups["name"].Value)+@"\(\k<list>\)\.slice\(0,16\)";known=Regex.IsMatch(code,reader)&&Regex.IsMatch(code,list);}
