    }
    public static string ReadStartup(string install,out string format){format=null;var asar=Path.Combine(install,"app","resources","app.asar");using(var file=File.OpenRead(asar))using(var reader=new BinaryReader(file)){
        if(reader.ReadUInt32()!=4)throw new InvalidDataException("无法识别桌面资源头。");long header=reader.ReadUInt32();reader.ReadUInt32();int size=reader.ReadInt32();if(header<8||header>16*1024*1024||size<1||size>header-8)throw new InvalidDataException("桌面资源头不完整。");var bytes=reader.ReadBytes(size);if(bytes.Length!=size)throw new EndOfStreamException("桌面资源头被截断。");var data=NativeData.Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(bytes));Func<object,Dictionary<string,object>> map=x=>(Dictionary<string,object>)x;var entries=map(map(map(map(map(data["files"])[".vite"])["files"])["build"])["files"]);var choices=entries.Where(x=>Regex.IsMatch(x.Key,@"^(application-network-startup|early-bootstrap)-.*\.js$")).ToArray();var implementations=new List<Tuple<string,string>>();
