        if(implementations.Count!=1)throw new InvalidDataException("无法唯一识别运行时实现。");format=implementations[0].Item1.StartsWith("application-network-startup-",StringComparison.Ordinal)?"direct":"streamed";return implementations[0].Item2;
    }}
    public NativeCuaResult Run(bool repair,string reportRoot){using(var mutex=new System.Threading.Mutex(false,"Local\\CodexCUARepair-"+System.Security.Principal.WindowsIdentity.GetCurrent().User.Value)){bool owned=false;try{try{owned=mutex.WaitOne(0);}catch(System.Threading.AbandonedMutexException){owned=true;}if(!owned)throw new IOException("另一个 CUA 或浏览器操作正在运行，请等待完成。");return RunCore(repair,reportRoot);}finally{if(owned)mutex.ReleaseMutex();}}}
    NativeCuaResult RunCore(bool repair,string reportRoot){
        var app=services.Desktop.Discover();string format="direct";var code=app.StartupCode??ReadStartup(app.Install,out format);ValidateAlgorithm(code,format);var inventory=NativeTree.Read(app.Source);string id=RuntimeId(app.Source);string target=Path.Combine(paths.RuntimeRoot,id);NativeData.NoLinks(paths.RuntimeRoot);var patch=Directory.Exists(target)?NativeBrowserPatch.Load(paths,app,target):null;if(Directory.Exists(target)&&patch==null){foreach(var source in Directory.GetFiles(app.Source,"cua-repl.mjs",SearchOption.AllDirectories)){var launcher=Path.Combine(target,source.Substring(app.Source.TrimEnd('\\').Length+1));if(File.Exists(launcher)&&Hash(launcher)!=Hash(source))throw new IOException("浏览器入口包含未识别修改，停止覆盖。");}}var result=new NativeCuaResult{RuntimeId=id,Target=target,Passed=inventory.Same(target)};
        if(result.Passed||!repair)return result;
        if(services.Processes.List(paths,app).Count>0)throw new InvalidOperationException("CUA 修改前应用仍在运行，停止修复。");var current=services.Desktop.Discover();if(current.FullName!=app.FullName||current.Install!=app.Install||RuntimeId(current.Source)!=id)throw new InvalidOperationException("桌面应用在检查后发生变化，停止修复。");
        Directory.CreateDirectory(paths.RuntimeRoot);Directory.CreateDirectory(reportRoot);var suffix=DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8);NativeTree previous=null;
        if(Directory.Exists(target)){previous=NativeTree.Read(target);result.Backup=Path.Combine(paths.RuntimeRoot,".backup-"+id+"-"+suffix);Directory.Move(target,result.Backup);}
        try{
            if(services.Processes.List(paths,app).Count>0)throw new InvalidOperationException("应用重新启动，停止 CUA 写入。");Copy(inventory,target);
            if(!inventory.Same(target)||!inventory.Same(app.Source))throw new IOException("CUA 源或目标校验不一致。");var latest=services.Desktop.Discover();if(latest.FullName!=app.FullName)throw new IOException("应用在修复中升级，停止并恢复原组件。");result.Passed=true;result.Changed=true;result.Report=Path.Combine(reportRoot,"cua-result.json");NativeData.Write(result.Report,NativeData.Json.Serialize(new{schema=1,package=app.FullName,result=result,original=previous}));services.Log("CUA 文件、目录、长度和 SHA-256 已验证。原目录备份："+(result.Backup??"原目录不存在"));return result;
